// The reference explicitly permits its small reduced-motion fades at animator scale zero.
private object ClayPromptDurationScale : MotionDurationScale { override val scaleFactor=1f }

private class ClayPromptState(auto:Boolean){
    var clock=0.0;var autoStart=0.0;var mode=if(auto)0 else 1;var lastTouch=-100.0;var touching=false;var focused=false
    var generation=0.0;var wipe=0.0;var frame=ClayPromptMotion.frame(0.0);var popCount=0;var swirl=false
    var shown=emptyList<Int>();val kinds=intArrayOf(0,1,2,3);val pops=Array(4){Animatable(0f)};val xs=Array(4){Animatable(0f)}
    val gen=Animatable(0f);val clear=Animatable(0f);var genJob:Job?=null;var resumeJob:Job?=null
}

@OptIn(ExperimentalLayoutApi::class)
@Composable fun ClayPrompt(autoPlay:Boolean=false){
    val C=ClayPromptTheme;val M=ClayPromptMotion
    val context=LocalContext.current;val density=LocalDensity.current;val view=LocalView.current
    val reduced=rememberLiveReducedMotion();val auto=autoPlay&&!reduced
    val lifecycle=LocalLifecycleOwner.current.lifecycle
    val scope=rememberCoroutineScope{ClayPromptDurationScale};val keyboard=LocalSoftwareKeyboardController.current;val focus=LocalFocusManager.current
    val regular=remember{FontFamily(androidx.compose.ui.text.font.Typeface(Typeface.createFromAsset(context.assets,"clayprompt/clayprompt_Inter-Regular.ttf")))}
    val medium=remember{FontFamily(androidx.compose.ui.text.font.Typeface(Typeface.createFromAsset(context.assets,"clayprompt/clayprompt_Inter-Medium.ttf")))}
    val semi=remember{FontFamily(androidx.compose.ui.text.font.Typeface(Typeface.createFromAsset(context.assets,"clayprompt/clayprompt_Inter-SemiBold.ttf")))}
    val generateInteraction=remember{MutableInteractionSource()}
    val generatePressed by generateInteraction.collectIsPressedAsState()
    val generateScale by animateFloatAsState(if(generatePressed&&!reduced)0.96f else 1f,spring(dampingRatio=0.75f,stiffness=500f),label="Generate press")
    val audio=remember{ClayPromptAudio(context)};DisposableEffect(audio){onDispose{audio.close()}}
    val s=remember{ClayPromptState(auto)};val dust=remember{ClayPromptDust()}
    val shader=remember{if(Build.VERSION.SDK_INT>=33) RuntimeShader(CLAY_PROMPT_AGSL) else null}
    val paint=remember{Paint(Paint.ANTI_ALIAS_FLAG)}
    var tick by remember{mutableIntStateOf(0)};var text by remember{mutableStateOf("")};var typed by remember{mutableIntStateOf(0)}
    var manual by remember{mutableStateOf(!auto)};var editing by remember{mutableStateOf(false)};var generated by remember{mutableStateOf(false)}
    var shown by remember{mutableStateOf(emptyList<Int>())}
    val words=remember{mutableMapOf<Int,Offset>()}
    BlockSystemBars(darkIcons=false)
    BoxWithConstraints(Modifier.fillMaxSize().background(C.page).clipToBounds()){
        val top=WindowInsets.statusBars.getTop(density)/density.density.toDouble()
        val bottom=WindowInsets.navigationBars.getBottom(density)/density.density.toDouble()
        val lift=max(0.0,WindowInsets.ime.getBottom(density)/density.density.toDouble()-bottom)
        val L=remember(maxWidth,maxHeight,top,bottom){C.layout(maxWidth.value.toDouble(),maxHeight.value.toDouble(),top,bottom)}
        fun takeOver(){s.lastTouch=s.clock;s.resumeJob?.cancel();s.resumeJob=null;if(s.mode==0){
                val frame=s.frame;val count=max(1.0,frame.pops.sum());s.mode=1;s.genJob?.cancel()
                scope.launch{s.gen.snapTo(s.generation.toFloat())}
                for(i in 0..3){s.kinds[i]=i;scope.launch{s.pops[i].snapTo(if(i<3)frame.pops[i].toFloat()else 0f)};scope.launch{s.xs[i].snapTo(M.slot(i,count,L.w).toFloat())}}
            }
            if(s.wipe>0)scope.launch{s.clear.animateTo(0f,tween(200))}}
        fun burst(kind:Int,index:Int,count:Int){val from=words[kind]?:Offset((L.w/2).toFloat(),(L.composer-lift+30).toFloat());dust.emit(from.x.toDouble(),from.y.toDouble(),M.slot(index,max(1,count).toDouble(),L.w),L.ty-lift,kind,s.clock,M.look(s.generation).blobR)}
        fun animateGen(to:Float,duration:Int,linear:Boolean=false,velocity:Float?=null){s.genJob?.cancel();s.genJob=scope.launch{
            if(velocity!=null)s.gen.animateTo(to,spring(dampingRatio=1f,stiffness=if(duration==700)130f else 240f),initialVelocity=velocity)
            else s.gen.animateTo(to,tween(duration,easing=if(linear)LinearEasing else CubicBezierEasing(0.23f,1f,0.32f,1f)))
            s.lastTouch=s.clock}}
        fun change(value:String){takeOver();manual=true;text=value;val next=C.kinds(value);val added=next.filter{it !in s.shown}
            for(i in 0..3){if(i<next.size)s.kinds[i]=next[i];val want=if(i<next.size)1f else 0f;val tx=M.slot(i,max(1,next.size).toDouble(),L.w).toFloat();val fresh=i<next.size&&next[i] in added
                scope.launch{if(fresh||reduced)s.xs[i].snapTo(tx) else s.xs[i].animateTo(tx,spring(0.8f,300f))}
                scope.launch{if(fresh)s.pops[i].snapTo(0f);s.pops[i].animateTo(want,if(reduced)tween(200) else spring(if(fresh)0.5f else 0.8f,if(fresh)240f else 300f))}}
            if(added.isNotEmpty()){val k=added.last();view.performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);if(!reduced){audio.play("pop");burst(k,next.indexOf(k),next.size)}}
            s.shown=next;shown=next;if(s.generation>0.01){animateGen(0f,600);generated=false}}
        LaunchedEffect(auto,reduced,L){s.mode=if(auto)0 else 1;s.autoStart=s.clock;if(reduced){manual=true;typed=0}
            var prev=0L;var oldG=s.generation
            while(true){withFrameNanos{now->
                val dt=if(prev==0L)0.016 else min(0.05,(now-prev)/1e9);prev=now
                if(!lifecycle.currentState.isAtLeast(Lifecycle.State.STARTED))return@withFrameNanos
                s.clock+=dt
                if(s.mode==0){val t=(s.clock-s.autoStart)%M.LOOP;s.frame=M.frame(t);s.generation=s.frame.g;s.wipe=s.frame.clear
                    if(typed!=s.frame.chars)typed=s.frame.chars
                    val count=s.frame.pops.count{it>0.02};if(count>s.popCount&&!reduced)burst(count-1,count-1,count);s.popCount=count
                }else{s.generation=s.gen.value.toDouble();s.wipe=s.clear.value.toDouble()
                    if(oldG<=0.22&&s.generation>0.22){if(!reduced)audio.play("melt");view.performHapticFeedback(HapticFeedbackConstants.CONTEXT_CLICK)}
                    if(oldG<=0.55&&s.generation>0.55){if(!reduced)audio.play("bloom");view.performHapticFeedback(HapticFeedbackConstants.CONFIRM);generated=true}
                    if(auto&&s.resumeJob==null&&!s.focused&&!s.touching&&(s.generation<0.001||s.generation>0.999)&&s.clock-s.lastTouch>2){
                        s.resumeJob=scope.launch{s.clear.animateTo(1f,tween(700,easing=CubicBezierEasing(0.23f,1f,0.32f,1f)));s.gen.snapTo(0f);s.clear.snapTo(0f);for(p in s.pops)p.snapTo(0f);text="";shown=emptyList();s.shown=emptyList();generated=false;typed=0;manual=false;s.autoStart=s.clock;s.mode=0;s.resumeJob=null}}
                }
                val swirl=s.generation>0.2&&s.generation<0.5;if(swirl&&!s.swirl&&!reduced)dust.emit(L.cx,L.cy,L.cx,L.cy,-1,s.clock,M.look(s.generation).blobR);s.swirl=swirl
                if(!reduced)dust.step(min(dt,0.033),s.generation,s.wipe,L.cx,L.cy,M.look(s.generation).blobR)
                oldG=s.generation;tick++
            }}
        }
        val value=if(manual)text else C.PROMPT.take(typed)
        Canvas(Modifier.fillMaxSize()){
            tick;val g=s.generation;val wipe=s.wipe;val f=s.frame
            val pops=DoubleArray(4){if(s.mode==0)if(it<3)f.pops[it] else 0.0 else s.pops[it].value.toDouble()}
            val count=if(s.mode==0)max(1.0,pops.sum())else max(1,s.shown.size).toDouble()
            val kinds=if(s.mode==0)intArrayOf(0,1,2,3) else s.kinds
            val sofa=(0..3).any{kinds[it]==1&&pops[it]>0.01}
            val passes=if(reduced)listOf(0.0 to (1-g).coerceIn(0.0,1.0),1.0 to g.coerceIn(0.0,1.0))else listOf(g to 1.0)
            for((drawG,opacity) in passes){
            val look=M.look(drawG)
            val poses=Array(4){i->M.pose(drawG,if(s.mode==0)M.slot(i,count,L.w) else s.xs[i].value.toDouble(),L.ty-lift,34.0,M.composed(kinds[i],sofa,L.x,L.y,L.cw,L.ch),L.cx,L.cy)}
            withTransform({scale(density.density,density.density,Offset.Zero)}){
                drawRoundRect(C.line.copy(alpha=((1-look.reveal*(1-wipe))*0.9*opacity).toFloat()),Offset((L.x+0.5).toFloat(),(L.y+0.5).toFloat()),Size((L.cw-1).toFloat(),(L.ch-1).toFloat()),CornerRadius(28f),style=Stroke(1.5f,pathEffect=PathEffect.dashPathEffect(floatArrayOf(6f,6f))))
            }
            if(Build.VERSION.SDK_INT>=33&&shader!=null){shader.setFloatUniform("uDensity",density.density);shader.setFloatUniform("uPixelRatio",density.density)
                for(i in 0..3){val p=poses[i];shader.setFloatUniform("uO$i",p.x.toFloat(),p.y.toFloat(),p.size.toFloat(),(max(0.0,pops[i])*(1-wipe)).toFloat())
                    shader.setFloatUniform("uP$i",kinds[i].toFloat(),(if(reduced)0.0 else 0.28*sin(s.clock*1.1+i*1.7)*(1-look.reveal*0.6)).toFloat(),(p.squash+0.5*(pops[i]-1).coerceIn(-0.2,0.2)).toFloat(),(0.6+0.4*look.night).toFloat())}
                shader.setFloatUniform("uMerge",L.cx.toFloat(),L.cy.toFloat(),look.k.toFloat(),look.pull.toFloat());shader.setFloatUniform("uCard",L.x.toFloat(),L.y.toFloat(),L.cw.toFloat(),L.ch.toFloat());shader.setFloatUniform("uReveal",look.reveal.toFloat(),look.night.toFloat());shader.setFloatUniform("uBlobR",look.blobR.toFloat());shader.setFloatUniform("uFade",(1-wipe).toFloat());shader.setFloatUniform("uTime",if(reduced)0f else s.clock.toFloat());paint.shader=shader;paint.alpha=(opacity*255).roundToInt()
                drawIntoCanvas{it.nativeCanvas.drawRect(0f,0f,size.width,size.height,paint)}
            }else withTransform({scale(density.density,density.density,Offset.Zero)}){
                drawRoundRect(Color(0xFF282344).copy(alpha=(look.reveal*(1-wipe)*opacity).toFloat()),Offset(L.x.toFloat(),L.y.toFloat()),Size(L.cw.toFloat(),L.ch.toFloat()),CornerRadius(28f))
                for(i in 0..3){val p=poses[i];val radius=(p.size*max(0.0,pops[i])*(1-wipe)).toFloat();if(radius>0)drawCircle(C.tints[kinds[i]].copy(alpha=opacity.toFloat()),radius,Offset(p.x.toFloat(),p.y.toFloat()))}}
            }
            if(!reduced)drawIntoCanvas{val nc=it.nativeCanvas;nc.save();nc.scale(density.density,density.density);dust.draw(nc);nc.restore()}
        }
        Row(Modifier.offset(16.dp,L.bar.dp).width((L.w-32).dp).height(44.dp),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.SpaceBetween){
            Box(Modifier.size(40.dp).background(C.surface,RoundedCornerShape(20.dp)).semantics{contentDescription="Menu";role=Role.Button}.clickable{},contentAlignment=Alignment.Center){Canvas(Modifier.size(20.dp)){drawLine(C.ink,Offset(4*size.width/20,6.5f*size.height/20),Offset(16*size.width/20,6.5f*size.height/20),1.8f*density.density,StrokeCap.Round);drawLine(C.ink,Offset(4*size.width/20,13.5f*size.height/20),Offset(12*size.width/20,13.5f*size.height/20),1.8f*density.density,StrokeCap.Round)}}
            Text("Mold",fontFamily=semi,fontSize=17.sp,color=C.ink)
            Row(Modifier.height(32.dp).background(C.surface,RoundedCornerShape(16.dp)).padding(horizontal=12.dp).semantics{contentDescription="24 credits"},verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(6.dp)){ClayPromptStar(14.dp,C.accent);Text("24",fontFamily=semi,fontSize=15.sp,color=C.ink)}
        }
        Box(Modifier.offset(L.x.dp,L.y.dp).size(L.cw.dp,L.ch.dp).semantics{contentDescription=if(generated)"Picture: ${value.ifEmpty{C.PROMPT}}, sculpted in clay. Drag down to melt it back into the prompt" else "Empty picture. Describe a scene below.";role=Role.Image}.pointerInput(L,reduced){
            awaitEachGesture{val down=awaitFirstDown(requireUnconsumed=false);takeOver();s.touching=true;val from=s.generation;val tracker=VelocityTracker();tracker.addPosition(down.uptimeMillis,down.position);var dy=0f;var caught=false;var failed=false
                if(from>=0.5)s.genJob?.cancel()
                do{val event=awaitPointerEvent();val change=event.changes.firstOrNull{it.id==down.id}?:break;tracker.addPosition(change.uptimeMillis,change.position)
                    dy=(change.position.y-down.position.y)/density.density;val dx=(change.position.x-down.position.x)/density.density
                    if(!caught&&abs(dx)>16)failed=true
                    if(!failed&&dy>8)caught=true
                    if(caught&&from>=0.5){change.consume();s.lastTouch=s.clock;scope.launch{s.gen.snapTo((from-max(0f,dy)/340).coerceIn(0.0,1.0).toFloat())}}
                    val pressed=change.pressed
                }while(pressed)
                s.touching=false;s.lastTouch=s.clock
                if(from>=0.5){val vy=tracker.calculateVelocity().y/density.density;val back=dy>150||vy>900;animateGen(if(back)0f else 1f,if(back)700 else 520,velocity=-vy/340);if(back)generated=false}
            }
        },contentAlignment=Alignment.Center){
            Column(Modifier.padding(horizontal=32.dp).graphicsLayer{tick;alpha=((1-min(1.0,s.generation*3))*(1-min(1.0,if(s.mode==0)s.frame.pops.sumOf{max(0.0,it)} else s.pops.sumOf{max(0.0,it.value.toDouble())}))).toFloat()},horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(8.dp)){
                Text("Describe a scene",fontFamily=semi,fontSize=20.sp,color=C.ink);Text("Its things turn into clay. Try a cat, a sofa, the moon or a plant.",fontFamily=regular,fontSize=15.sp,lineHeight=21.sp,color=C.mute,textAlign=androidx.compose.ui.text.style.TextAlign.Center)
            }
        }
        Row(Modifier.offset(L.x.dp,L.caption.dp).width(L.cw.dp).height(32.dp).padding(horizontal=4.dp).graphicsLayer{tick;alpha=((if(reduced)s.generation else ((s.generation-0.8)/0.2).coerceIn(0.0,1.0))*(1-s.wipe)).toFloat()},verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(12.dp)){
            Text("“${value.ifEmpty{C.PROMPT}}”",Modifier.weight(1f),fontFamily=regular,fontSize=15.sp,color=C.mute,maxLines=1,overflow=TextOverflow.Ellipsis)
            if(!auto||generated)Box(Modifier.height(32.dp).background(C.surface,RoundedCornerShape(16.dp)).clickable{takeOver();animateGen(0f,if(reduced)200 else 900);generated=false}.padding(horizontal=12.dp),contentAlignment=Alignment.Center){Text("Remix",fontFamily=medium,fontSize=14.sp,color=C.ink)}
        }
        Column(Modifier.offset(16.dp,(L.composer-lift).dp).width((L.w-32).dp).height(120.dp).background(C.surface,RoundedCornerShape(24.dp)).border(Dp.Hairline,C.line,RoundedCornerShape(24.dp)).padding(12.dp),verticalArrangement=Arrangement.SpaceBetween){
            Box(Modifier.weight(1f).fillMaxWidth().padding(horizontal=2.dp,vertical=2.dp)){
                FlowRow(Modifier.graphicsLayer{tick;alpha=(1-s.wipe).toFloat()},horizontalArrangement=Arrangement.spacedBy(5.dp),verticalArrangement=Arrangement.spacedBy(2.dp)){
                    if(value.isEmpty()){
                        if(editing)Box(Modifier.width(2.dp).height(20.dp).background(C.accent,RoundedCornerShape(1.dp)))
                        Text("Describe a scene…",fontFamily=regular,fontSize=17.sp,lineHeight=24.sp,color=C.faint)
                    }else{
                        val parts=value.split(" ")
                        parts.forEachIndexed{i,word->val k=C.kind(word);val complete=k>=0&&(manual||i<parts.lastIndex||typed>=C.PROMPT.length)
                            Text(word,Modifier.background(if(complete)C.tints[k].copy(alpha=0.15f)else Color.Transparent,RoundedCornerShape(6.dp)).padding(horizontal=2.dp).onGloballyPositioned{coordinates->
                                if(k>=0){val rect=coordinates.boundsInRoot();words[k]=Offset(rect.center.x/density.density,rect.center.y/density.density)}
                            },fontFamily=regular,fontSize=17.sp,lineHeight=24.sp,color=if(complete)C.tints[k]else C.ink)
                        }
                        if(editing||(!manual&&typed<C.PROMPT.length))Box(Modifier.width(2.dp).height(20.dp).background(C.accent,RoundedCornerShape(1.dp)))
                    }
                }
                BasicTextField(value=if(manual)text else value,onValueChange=::change,modifier=Modifier.fillMaxSize().onFocusChanged{state->if(state.isFocused){takeOver();manual=true};editing=state.isFocused;s.focused=state.isFocused;s.lastTouch=s.clock}.semantics{contentDescription="Prompt. Describe a scene. A cat, a sofa, the moon or a plant become clay."},textStyle=TextStyle(fontFamily=regular,fontSize=17.sp,lineHeight=24.sp,color=Color.Transparent),cursorBrush=SolidColor(Color.Transparent),keyboardOptions=KeyboardOptions(capitalization=KeyboardCapitalization.None,autoCorrectEnabled=false))
            }
            Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){
                Box(Modifier.height(32.dp).border(Dp.Hairline,C.line,RoundedCornerShape(16.dp)).padding(horizontal=12.dp).semantics{contentDescription="Style: clay"},contentAlignment=Alignment.Center){Text("Clay",fontFamily=medium,fontSize=14.sp,color=C.mute)}
                val enabled=auto||shown.isNotEmpty()
                Row(Modifier.height(44.dp).graphicsLayer{tick;val p=if(s.mode==0)s.frame.press else 0.0;scaleX=(1-0.04*p).toFloat()*generateScale;scaleY=scaleX;alpha=if(enabled)1f else 0.4f}.background(C.accent,RoundedCornerShape(22.dp)).clickable(interactionSource=generateInteraction,indication=null,enabled=enabled,role=Role.Button){takeOver();if(s.shown.isNotEmpty()||s.pops.sumOf{it.value.toDouble()}>0.5||(s.frame.pops.sum()>0.5&&!manual)){keyboard?.hide();focus.clearFocus();animateGen(1f,if(reduced)300 else (2400*(1-s.generation)).toInt().coerceAtLeast(0),linear=true)}}.padding(horizontal=16.dp),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(8.dp)){ClayPromptStar(16.dp,C.accentInk);Text("Generate",fontFamily=semi,fontSize=16.sp,color=C.accentInk)}
            }
        }
        Canvas(Modifier.fillMaxSize()){
            tick;if(s.mode==0){val f=s.frame;val x=if(f.fingerAt==0)L.w-86 else L.cx+40;val y=if(f.fingerAt==0)L.composer+86 else L.y+L.ch*0.4+f.dragY
                val r=(22*(1-0.12*f.press)*density.density).toFloat();val at=Offset((x*density.density).toFloat(),(y*density.density).toFloat());drawCircle(Color.White.copy(alpha=(0.16*f.finger).toFloat()),r,at);drawCircle(Color.White.copy(alpha=(0.55*f.finger).toFloat()),r,at,style=Stroke(1.5f*density.density))}
        }
    }
}

@Composable private fun ClayPromptStar(size:Dp,color:Color){Canvas(Modifier.size(size)){
    val p=Path();val s=this.size.width/14;p.moveTo(7*s,1*s);p.cubicTo(7.6f*s,4.6f*s,9.4f*s,6.4f*s,13*s,7*s);p.cubicTo(9.4f*s,7.6f*s,7.6f*s,9.4f*s,7*s,13*s);p.cubicTo(6.4f*s,9.4f*s,4.6f*s,7.6f*s,1*s,7*s);p.cubicTo(4.6f*s,6.4f*s,6.4f*s,4.6f*s,7*s,1*s);p.close();drawPath(p,color)
}}
